// AUTO-GENERATED file — do not edit. Source of truth: bundled-skills/.
// Regenerated by `npm run generate:system-skills` (also via `prebuild:*` /
// `pretest` / `prelint` npm hooks and `src-tauri/build.rs` for bare cargo).
//
// Reads `bundled-skills/<name>/SKILL.md` and writes two files:
//   - src-tauri/src/system_skills.generated.rs (Rust `pub const SYSTEM_SKILLS: &[&str]`)
//   - src/shared/systemSkills.generated.ts      (TS `export const SYSTEM_SKILLS = [...] as const` + union type)
//
// Both targets are sorted lexicographically and filtered to entries that have
// a SKILL.md, so a directory without one is silently skipped (matches the
// legacy `src-tauri/src/commands.rs::SYSTEM_SKILLS` semantics where utility
// skills without SKILL.md were never in the list).

import { readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, '..');
const bundledDir = join(repoRoot, 'bundled-skills');

if (!existsSync(bundledDir)) {
  console.error(`[generate-system-skills] bundled-skills/ not found at ${bundledDir}`);
  process.exit(1);
}

const names = readdirSync(bundledDir, { withFileTypes: true })
  .filter((d) => d.isDirectory() && existsSync(join(bundledDir, d.name, 'SKILL.md')))
  .map((d) => d.name)
  .sort();

const rsLines = names.map((n) => `    "${n}",`).join('\n');
const rsHeader = [
  '// AUTO-GENERATED by scripts/generate-system-skills.mjs — do not edit.',
  '// Source of truth: bundled-skills/ filesystem.',
  '//',
  '// Outer #[allow] (not #![allow]) because this file is include!-ed:',
  '// the inner attribute would attach to the enclosing item (the include!',
  '// macro call site, which has no const), producing',
  '// "the inner attribute doesn\'t annotate this constant item" errors.',
  '#[allow(clippy::all)]',
  'pub const SYSTEM_SKILLS: &[&str] = &[',
].join('\n');
writeFileSync(
  join(repoRoot, 'src-tauri/src/system_skills.generated.rs'),
  `${rsHeader}\n${rsLines}\n];\n`,
);

const tsLines = names.map((n) => `  '${n}',`).join('\n');
writeFileSync(
  join(repoRoot, 'src/shared/systemSkills.generated.ts'),
  `// AUTO-GENERATED by scripts/generate-system-skills.mjs — do not edit.
// Source of truth: bundled-skills/ filesystem.
export const SYSTEM_SKILLS = [
${tsLines}
] as const;
export type SystemSkillName = (typeof SYSTEM_SKILLS)[number];
`,
);

console.log(`[generate-system-skills] wrote ${names.length} skills`);